package com.wizzadrds.theworldremembers.voice; import java.io.*;import java.nio.file.*; public final class LocalTtsAdapter{private final String executable;public LocalTtsAdapter(String executable){this.executable=executable;}public Path synthesize(String text,Path output)throws IOException,InterruptedException{Path parent=output.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);Process p=new ProcessBuilder(executable,text,output.toAbsolutePath().toString()).redirectErrorStream(true).start();String log=new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);int code=p.waitFor();if(code!=0)throw new IOException("Local TTS exited "+code+": "+log);if(!Files.isRegularFile(output))throw new IOException("TTS produced no output");return output;}}
